// === Tab: mySketch ===
// if you've gotten this far, you might as well change a few variables below to see what happens...


int num = 24; // how many rows and columns
float s = 3; // size of the dots
float reflex = 0.3; // how fast ir reacts when clicked. Range: [0, 1[
float aperture = 64; // how much it blurs

color bg = color(223, 8, 47); // background
color fg1 = color(153, 217, 140);// foreground
color fg2 = color(43, 147, 72);



void setup() {
  //size(800, 800); 

  // all 3D is fake :)

  fullScreen();
  noStroke();
  frameRate(25);

  aa = new float[8];
  bb = new float[aa.length];
  reset();
}

void mouseClicked() {
  reset();
}


float t = 0; // keeps the time

float[] aa; // great naming conventions, I know...
float[] bb;
float transition = 0;


// if you're feeling adventurous/you-know-what-you're-doing, please mess with the code below :)

void reset() {
  for (int i = 0; i<bb.length; i++) {
    float v = random(1, 8);
    bb[i] = aa[i];
    aa[i] = random(2)<1?v:-v;
  }
  transition = 1;
}
void draw() {
  t+=0.0008; // enables time traveling

  background(255);

  transition*=(1-reflex);


  for (float v = 0; v<num; v++) {
    for (float u = 0; u<num; u++) {
      float h = 42
        *sin((aa[0]*u-aa[1]*v)/num+4.2*aa[4]*t+aa[6])
        *cos((aa[2]*v+aa[3]*u )/num+aa[5]*t+aa[7]);

      float h2 = 42
        *sin((bb[0]*u-bb[1]*v)/num+4.2*bb[4]*t+bb[6])
        *cos((bb[2]*v+bb[3]*u )/num+bb[5]*t+bb[7]);
      h = lerp(h, h2, transition);

      float u1 = u/num*2-1;
      float v1 = v/num*2-1;

      float u2 = cos(t)*u1 + sin(t)*v1;
      float v2 = sin(t)*u1 - cos(t)*v1; // transformation after transformation, I'm not entirely sure what's going on here anymore. #dontTouchItItWorks

      let u3 = u2/2+0.5;
      let v3 = v2/2+0.5;

      let x = u3*max(width, height);
      let y = v3*max(width, height);

      let a = x-y;
      let b = x+y;

      pushMatrix();
      translate(0, 0);
      translate(width/2, 0);
      let dist = 1.5-b/2/height-h/500;
      scale(atan(1/dist)*3.4);  // a little math, but mostly magic
      translate(-width/2, -height/3.5);

      let blur = (1-dist)*aperture;
      fill(lerpColor(fg1, fg2, constrain(map(blur, -aperture/3, aperture/2, 0, 1), 0, 1)), // blend the colors
        min(s*255/max(sq(blur/2)*2, 1), 128)); // add transparency

      translate(0, -h); // creates the waves
      ellipse(a/4+width/2, b/42+height/2, max(abs(blur), s), max(abs(blur), s));
      popMatrix();
    }
  }
}

